from storage_client import get_s3_client
from storage_models import PresignedUrlResult


def create_presigned_download_url(bucket_name: str, object_name: str, expiration: int = 3600, config: dict = None) -> PresignedUrlResult:
    config = config or {}
    s3_client = get_s3_client(region_name=config.get("region"))
    url = s3_client.generate_presigned_url(
        'get_object',
        Params={'Bucket': bucket_name, 'Key': object_name},
        ExpiresIn=expiration
    )
    return PresignedUrlResult(url=url)

from storage_client import get_s3_client
from storage_models import ObjectMetadataResult


def get_object_metadata(bucket_name: str, object_name: str, config: dict = None) -> ObjectMetadataResult:
    config = config or {}
    s3_client = get_s3_client(region_name=config.get("region"))
    response = s3_client.head_object(Bucket=bucket_name, Key=object_name)
    return ObjectMetadataResult(metadata=response)

from storage_client import get_s3_client
from storage_models import ListObjectsResult


def list_objects_with_prefix(bucket_name: str, prefix: str = "", config: dict = None) -> ListObjectsResult:
    config = config or {}
    s3_client = get_s3_client(region_name=config.get("region"))
    object_names = []
    paginator = s3_client.get_paginator('list_objects_v2')
    pages = paginator.paginate(Bucket=bucket_name, Prefix=prefix)
    for page in pages:
        if "Contents" in page:
            for obj in page["Contents"]:
                object_names.append(obj["Key"])
    return ListObjectsResult(object_names=object_names)

from storage_client import get_textract_client
from storage_models import OCRResult


def run_ocr_on_stored_document(bucket_name: str, object_name: str, config: dict = None) -> OCRResult:
    config = config or {}
    textract_client = get_textract_client(region_name=config.get("region"))
    response = textract_client.detect_document_text(
        Document={'S3Object': {'Bucket': bucket_name, 'Name': object_name}}
    )
    extracted_text = []
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            extracted_text.append(item['Text'])
    return OCRResult(text="\n".join(extracted_text))

from storage_client import get_translate_client
from storage_models import TranslationResult


def translate_stored_text(text: str, source_language_code: str, target_language_code: str, config: dict = None) -> TranslationResult:
    config = config or {}
    translate_client = get_translate_client(region_name=config.get("region"))
    response = translate_client.translate_text(
        Text=text,
        SourceLanguageCode=source_language_code,
        TargetLanguageCode=target_language_code
    )
    return TranslationResult(translated_text=response['TranslatedText'])

from storage_client import get_comprehend_client
from storage_models import SummaryResult


def summarize_stored_asset_content(text: str, language_code: str = "en", config: dict = None) -> SummaryResult:
    config = config or {}
    comprehend_client = get_comprehend_client(region_name=config.get("region"))
    # For summarization, we can extract key phrases as a proxy
    response = comprehend_client.detect_key_phrases(
        Text=text,
        LanguageCode=language_code
    )
    key_phrases = [phrase['Text'] for phrase in response['KeyPhrases']]
    return SummaryResult(summary_text="; ".join(key_phrases))
